// 获取表格数据（已按 publish_date 降序排序）
const tableData = $input.first().json;
const records = tableData.data?.items || [];

console.log(`从飞书表格读取到 ${records.length} 条记录（已按发布日期降序排序）`);

if (records.length === 0) {
  console.warn('⚠️ 未读取到任何记录，请检查飞书表格配置');
  return [];
}

// 安全提取飞书字段的函数（处理 [{text: "...", type: "text"}] 格式）
function extractFeishuField(field, defaultValue = '') {
  if (!field) return defaultValue;

  // 如果是字符串，直接返回
  if (typeof field === 'string') return field;

  // 如果是数组
  if (Array.isArray(field)) {
    if (field.length === 0) return defaultValue;

    // 飞书格式：[{text: "...", type: "text"}]
    if (field[0] && typeof field[0] === 'object' && field[0].text) {
      return field.map(item => item.text).join(', ');
    }

    // 普通数组
    return field.join(', ');
  }

  // 如果是对象
  if (typeof field === 'object') {
    if (field.text) return field.text;
    if (field.link) return field.link;
  }

  return String(field);
}

// 计算近两天的时间戳（毫秒）
const twoDaysAgo = Date.now() - 2 * 24 * 60 * 60 * 1000;
// 计算近7天的时间戳（毫秒）
//const twoDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

console.log(`筛选近两天的数据，截止时间: ${new Date(twoDaysAgo).toLocaleString('zh-CN')}`);

// 筛选近两天的记录
const recentRecords = records.filter(record => {
  const fields = record.fields;
  if (!fields || !fields.publish_date) return false;

  // 处理时间戳（支持毫秒和秒两种格式）
  let timestamp = fields.publish_date;
  if (typeof timestamp === 'string') {
    timestamp = new Date(timestamp).getTime();
  } else if (timestamp < 10000000000) {
    // 如果是秒级时间戳，转换为毫秒
    timestamp = timestamp * 1000;
  }

  return timestamp >= twoDaysAgo;
});

console.log(`筛选出近两天的记录: ${recentRecords.length} 条`);

// 按相关度评分过滤和排序，取前10条
const sortedRecords = recentRecords
  .filter(record => {
    const score = record.fields?.relevance_score || 0;
    return score > 0;
  })
  .sort((a, b) => (b.fields.relevance_score || 0) - (a.fields.relevance_score || 0))
  .slice(0, 10);

console.log(`按评分排序并取前10条: ${sortedRecords.length} 条`);

if (sortedRecords.length === 0) {
  console.warn('⚠️ 近两天没有符合条件的资讯（评分>0），工作流将停止');
  return [];
}

// 格式化数据 - 使用飞书字段提取函数
const formattedRecords = sortedRecords.map((record, index) => {
  const fields = record.fields;

  const title = extractFeishuField(fields.title, '无标题');
  const summary = extractFeishuField(fields.summary || fields.description, '无摘要');
  const url = fields.url || '';  // url可能是字符串
  const source = extractFeishuField(fields.source, '未知来源');
  const keywords = extractFeishuField(fields.keywords, '');
  const category = extractFeishuField(fields.category, '');

  // 调试第一条记录
  if (index === 0) {
    console.log('\n=== 第一条记录提取结果 ===');
    console.log('原始 title 类型:', typeof fields.title);
    console.log('原始 title:', JSON.stringify(fields.title));
    console.log('提取后 title:', title);
    console.log('\n原始 summary 类型:', typeof fields.summary);
    console.log('原始 summary:', JSON.stringify(fields.summary).substring(0, 150) + '...');
    console.log('提取后 summary:', summary.substring(0, 150) + '...');
    console.log('\n原始 keywords:', JSON.stringify(fields.keywords));
    console.log('提取后 keywords:', keywords);
  }

  return {
    record_id: record.record_id,
    title: title,
    summary: summary,
    url: url,
    source: source,
    publish_date: fields.publish_date,
    relevance_score: fields.relevance_score || 0,
    keywords: keywords,
    category: category,
    status: fields.status || '已处理'
  };
});

console.log(`\n最终处理记录数: ${formattedRecords.length}`);
console.log('记录来源分布:', formattedRecords.reduce((acc, record) => {
  acc[record.source] = (acc[record.source] || 0) + 1;
  return acc;
}, {}));
console.log('平均评分:', (formattedRecords.reduce((sum, r) => sum + r.relevance_score, 0) / formattedRecords.length).toFixed(1));

return formattedRecords;

// 获取AI分析结果
const analysisResult = $input.first().json;

console.log('=== Format Feishu Card 调试信息 ===');
console.log('原始分析结果:', JSON.stringify(analysisResult, null, 2));

// 更安全的数据提取 - 支持多种数据格式
let selectedNews = [];
let todayHotspot = 'AI技术发展';
let industryTrend = 'AI技术持续创新';
let recommendationReason = '精选优质AI资讯';

// 尝试从不同位置获取数据
if (analysisResult.output && analysisResult.output['精选资讯']) {
  selectedNews = analysisResult.output['精选资讯'];
  todayHotspot = analysisResult.output['今日热点'] || todayHotspot;
  industryTrend = analysisResult.output['行业趋势'] || industryTrend;
  recommendationReason = analysisResult.output['推荐理由'] || recommendationReason;
} else if (analysisResult['精选资讯']) {
  selectedNews = analysisResult['精选资讯'];
  todayHotspot = analysisResult['今日热点'] || todayHotspot;
  industryTrend = analysisResult['行业趋势'] || industryTrend;
  recommendationReason = analysisResult['推荐理由'] || recommendationReason;
} else if (Array.isArray(analysisResult)) {
  // 如果整个结果就是数组
  selectedNews = analysisResult;
} else {
  console.log('无法找到精选资讯数据，使用空数组');
  selectedNews = [];
}

console.log(`AI精选了 ${selectedNews.length} 条资讯`);
console.log('今日热点:', todayHotspot);
console.log('行业趋势:', industryTrend);
console.log('推荐理由:', recommendationReason);

// 确保 selectedNews 是数组
if (!Array.isArray(selectedNews)) {
  console.log('selectedNews 不是数组，转换为数组');
  selectedNews = [];
}

// 构建飞书卡片消息
const currentDate = new Date().toLocaleDateString('zh-CN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'long'
});

// 构建卡片内容
const cardElements = [
  {
    "tag": "div",
    "text": {
      "tag": "lark_md",
      "content": `# 🤖 AI资讯精选 - ${currentDate}\n\n**今日热点**: ${todayHotspot}\n\n**行业趋势**: ${industryTrend}\n\n**推荐理由**: ${recommendationReason}\n\n---`
    }
  }
];

// 为每条精选资讯添加卡片元素
selectedNews.forEach((news, index) => {
  const importanceEmoji = news.重要性 === '高' ? '🔥' : news.重要性 === '中' ? '⭐' : '📰';
  const keywordsText = Array.isArray(news.关键词) ? news.关键词.join('、') : news.关键词 || '';
  const categoryText = Array.isArray(news.分类) ? news.分类.join('、') : news.分类 || '';

  cardElements.push({
    "tag": "div",
    "text": {
      "tag": "lark_md",
      "content": `## ${importanceEmoji} ${news.标题}\n\n**来源**: ${news.来源} | **评分**: ${news.评分}/100\n\n**摘要**: ${news.摘要}\n\n**关键词**: ${keywordsText}\n\n**分类**: ${categoryText}\n\n[查看原文](${news.链接})\n\n---`
    }
  });
});

// 添加统计信息
cardElements.push({
  "tag": "div",
  "text": {
    "tag": "lark_md",
    "content": `\n📊 **统计信息**\n- 精选资讯: ${selectedNews.length} 条\n- 生成时间: ${new Date().toLocaleString('zh-CN')}\n- 数据来源: 飞书多维表格`
  }
});

// 构建完整的卡片消息
const cardMessage = {
  "msg_type": "interactive",
  "card": {
    "config": {
      "wide_screen_mode": true
    },
    "elements": cardElements,
    "header": {
      "title": {
        "tag": "plain_text",
        "content": "🤖 AI资讯精选"
      },
      "template": "blue"
    }
  }
};

console.log('构建的卡片消息:', JSON.stringify(cardMessage, null, 2));

return [{
  json: {
    message: cardMessage,
    webhook_url: $('Configuration').first().json.FEISHU_WEBHOOK_URL,
    selected_count: selectedNews.length,
    today_hotspot: todayHotspot,
    industry_trend: industryTrend
  }
}];

